package com.ncdex.instrument.kafka; import com.fasterxml.jackson.databind.ObjectMapper; import com.ncdex.instrument.service.InstrumentService; import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;
@Component public class OrderEventConsumer {private static final Logger log=LoggerFactory.getLogger(OrderEventConsumer.class);private final ObjectMapper mapper;private final InstrumentService service;public OrderEventConsumer(ObjectMapper m,InstrumentService s){mapper=m;service=s;}@KafkaListener(topics="order-events",groupId="instrument-service") public void consume(String json){try{var e=mapper.readValue(json,OrderCreatedEvent.class);if("ORDER_CREATED".equals(e.eventType()))service.recordOrder(e.instrumentId());}catch(Exception ex){log.error("Unable to process order event",ex);}}}